-- CF, comentários didáticos, lote 16 (arts. 221 a 250, os caputs restantes), só a partir do texto no banco. Já aplicado. Fecha a CF: 0 caputs vigentes sem comentário.
update legislacao set contexto = $c$Princípios da programação de rádio e televisão$c$, aplicacao_pratica = $a$Determina que a produção e a programação das emissoras de rádio e televisão atendam aos princípios de preferência a finalidades educativas, artísticas, culturais e informativas (I), promoção da cultura nacional e regional e estímulo à produção independente (II), regionalização da produção cultural, artística e jornalística conforme percentuais em lei (III) e respeito aos valores éticos e sociais da pessoa e da família (IV).$a$ where codigo='cf' and numero=221 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Conselho de Comunicação Social$c$, aplicacao_pratica = $a$Determina que o Congresso Nacional institua, como seu órgão auxiliar, o Conselho de Comunicação Social, na forma da lei, para os efeitos do capítulo da comunicação social.$a$ where codigo='cf' and numero=224 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Meio ambiente ecologicamente equilibrado$c$, aplicacao_pratica = $a$Reconhece a todos o direito ao meio ambiente ecologicamente equilibrado, bem de uso comum do povo e essencial à sadia qualidade de vida, e impõe ao Poder Público e à coletividade o dever de defendê-lo e preservá-lo para as presentes e futuras gerações. O § 1º lista as incumbências do Poder Público (I a VIII), entre elas o estudo prévio de impacto ambiental para obra ou atividade potencialmente causadora de significativa degradação (IV). O § 2º obriga quem explora recursos minerais a recuperar o ambiente degradado, o § 3º sujeita os infratores, pessoas físicas ou jurídicas, a sanções penais e administrativas independentemente da reparação do dano, o § 4º declara patrimônio nacional a Floresta Amazônica, a Mata Atlântica, a Serra do Mar, o Pantanal Mato-Grossense e a Zona Costeira, o § 5º torna indisponíveis as terras devolutas necessárias à proteção dos ecossistemas, o § 6º exige lei federal para a localização de usinas com reator nuclear e o § 7º afasta a crueldade das práticas desportivas com animais que sejam manifestações culturais registradas como patrimônio imaterial, mediante lei específica.$a$ where codigo='cf' and numero=225 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Família$c$, aplicacao_pratica = $a$Declara a família, base da sociedade, objeto de especial proteção do Estado. O § 1º dispõe que o casamento é civil e gratuita a celebração, o § 2º dá efeito civil ao casamento religioso, o § 3º reconhece a união estável entre o homem e a mulher como entidade familiar, devendo a lei facilitar sua conversão em casamento, e o § 4º reconhece como entidade familiar a comunidade formada por qualquer dos pais e seus descendentes. O § 5º estabelece o exercício igual, pelo homem e pela mulher, dos direitos e deveres da sociedade conjugal, o § 6º admite a dissolução do casamento civil pelo divórcio, o § 7º trata do planejamento familiar como livre decisão do casal, vedada qualquer forma coercitiva, e o § 8º determina a assistência à família e mecanismos para coibir a violência no âmbito de suas relações.$a$ where codigo='cf' and numero=226 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Inimputabilidade penal$c$, aplicacao_pratica = $a$Declara penalmente inimputáveis os menores de dezoito anos, sujeitos às normas da legislação especial.$a$ where codigo='cf' and numero=228 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Deveres entre pais e filhos$c$, aplicacao_pratica = $a$Impõe aos pais o dever de assistir, criar e educar os filhos menores e aos filhos maiores o dever de ajudar e amparar os pais na velhice, carência ou enfermidade.$a$ where codigo='cf' and numero=229 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Amparo às pessoas idosas$c$, aplicacao_pratica = $a$Impõe à família, à sociedade e ao Estado o dever de amparar as pessoas idosas, assegurando sua participação na comunidade, defendendo sua dignidade e bem-estar e garantindo-lhes o direito à vida. O § 1º manda executar os programas de amparo preferencialmente nos lares dos idosos e o § 2º garante aos maiores de sessenta e cinco anos a gratuidade dos transportes coletivos urbanos.$a$ where codigo='cf' and numero=230 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Legitimidade processual dos índios$c$, aplicacao_pratica = $a$Declara os índios, suas comunidades e organizações partes legítimas para ingressar em juízo em defesa de seus direitos e interesses, com intervenção do Ministério Público em todos os atos do processo.$a$ where codigo='cf' and numero=232 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Criação de Estado e encargos da União$c$, aplicacao_pratica = $a$Veda à União, direta ou indiretamente, assumir, em decorrência da criação de Estado, encargos referentes a despesas com pessoal inativo e com encargos e amortizações da dívida interna ou externa da administração pública, inclusive da indireta.$a$ where codigo='cf' and numero=234 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Normas básicas nos dez primeiros anos de Estado novo$c$, aplicacao_pratica = $a$Fixa normas básicas a serem observadas nos dez primeiros anos da criação de Estado: composição da Assembleia Legislativa (I), no máximo dez Secretarias (II), Tribunal de Contas com três membros (III), Tribunal de Justiça com sete Desembargadores (IV) e nomeação dos primeiros Desembargadores pelo Governador eleito (V). Tratam ainda do Estado proveniente de Território Federal (VI e IX), da nomeação dos primeiros Juiz de Direito, Promotor de Justiça e Defensor Público após concurso (VII), da Procuradoria-Geral, Advocacia-Geral e Defensoria-Geral até a Constituição Estadual (VIII), das nomeações posteriores, disciplinadas na Constituição Estadual (X), e do limite de cinquenta por cento da receita para despesas com pessoal (XI).$a$ where codigo='cf' and numero=235 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Serviços notariais e de registro$c$, aplicacao_pratica = $a$Determina que os serviços notariais e de registro sejam exercidos em caráter privado, por delegação do Poder Público. O § 1º remete a lei a regulação das atividades, a responsabilidade civil e criminal de notários, oficiais de registro e prepostos e a fiscalização de seus atos pelo Poder Judiciário, o § 2º atribui a lei federal as normas gerais para fixação de emolumentos e o § 3º exige concurso público de provas e títulos para o ingresso, vedando que serventia fique vaga por mais de seis meses sem abertura de concurso de provimento ou de remoção.$a$ where codigo='cf' and numero=236 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Venda de combustíveis$c$, aplicacao_pratica = $a$Determina que a lei ordene a venda e revenda de combustíveis de petróleo, álcool carburante e outros combustíveis derivados de matérias-primas renováveis, respeitados os princípios da Constituição.$a$ where codigo='cf' and numero=238 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$PIS/PASEP e seguro-desemprego$c$, aplicacao_pratica = $a$Destina a arrecadação das contribuições para o PIS e o PASEP ao financiamento do programa do seguro-desemprego, de outras ações da previdência social e do abono do § 3º. O § 1º reserva no mínimo 28% desses recursos ao financiamento de programas de desenvolvimento econômico por meio do BNDES, o § 2º preserva os patrimônios acumulados e veda a distribuição da arrecadação para as contas individuais, o § 3º assegura o abono anual de um salário mínimo aos empregados com remuneração mensal até o limite nele fixado, o § 3º-A trata do limite de elegibilidade desse benefício, o § 4º prevê contribuição adicional da empresa com rotatividade superior à média do setor e o § 5º manda avaliar e divulgar anualmente os programas financiados na forma do § 1º.$a$ where codigo='cf' and numero=239 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Contribuições ao sistema S$c$, aplicacao_pratica = $a$Ressalva do disposto no art. 195 as atuais contribuições compulsórias dos empregadores sobre a folha de salários destinadas às entidades privadas de serviço social e de formação profissional vinculadas ao sistema sindical.$a$ where codigo='cf' and numero=240 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Consórcios públicos e convênios de cooperação$c$, aplicacao_pratica = $a$Determina que União, Estados, Distrito Federal e Municípios disciplinem por lei os consórcios públicos e os convênios de cooperação entre os entes federados, autorizando a gestão associada de serviços públicos e a transferência total ou parcial de encargos, serviços, pessoal e bens essenciais à continuidade dos serviços transferidos.$a$ where codigo='cf' and numero=241 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Expropriação por culturas ilegais e trabalho escravo$c$, aplicacao_pratica = $a$Determina a expropriação das propriedades rurais e urbanas onde forem localizadas culturas ilegais de plantas psicotrópicas ou a exploração de trabalho escravo na forma da lei, com destinação à reforma agrária e a programas de habitação popular, sem indenização ao proprietário e sem prejuízo de outras sanções, observado, no que couber, o art. 5º. O parágrafo único manda confiscar todo bem de valor econômico apreendido em decorrência do tráfico ilícito de entorpecentes e drogas afins e da exploração de trabalho escravo, revertendo-o a fundo especial com destinação específica, na forma da lei.$a$ where codigo='cf' and numero=243 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Acessibilidade de logradouros e transportes existentes$c$, aplicacao_pratica = $a$Determina que a lei disponha sobre a adaptação dos logradouros, dos edifícios de uso público e dos veículos de transporte coletivo existentes, a fim de garantir acesso adequado às pessoas com deficiência, conforme o art. 227, § 2º.$a$ where codigo='cf' and numero=244 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Assistência às vítimas de crime doloso$c$, aplicacao_pratica = $a$Determina que a lei disponha sobre as hipóteses e condições em que o Poder Público dará assistência aos herdeiros e dependentes carentes de pessoas vitimadas por crime doloso, sem prejuízo da responsabilidade civil do autor do ilícito.$a$ where codigo='cf' and numero=245 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Vedação de medida provisória em artigo alterado por emenda$c$, aplicacao_pratica = $a$Veda a adoção de medida provisória na regulamentação de artigo da Constituição cuja redação tenha sido alterada por emenda promulgada entre 1º de janeiro de 1995 e a promulgação da emenda que inseriu o art. 246, inclusive.$a$ where codigo='cf' and numero=246 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Perda do cargo em atividades exclusivas de Estado$c$, aplicacao_pratica = $a$Determina que as leis previstas no art. 41, § 1º, III, e no art. 169, § 7º, estabeleçam critérios e garantias especiais para a perda do cargo pelo servidor estável que, em razão das atribuições de seu cargo efetivo, desenvolva atividades exclusivas de Estado. O parágrafo único condiciona a perda do cargo, na hipótese de insuficiência de desempenho, a processo administrativo com contraditório e ampla defesa.$a$ where codigo='cf' and numero=247 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Limite dos benefícios do regime geral$c$, aplicacao_pratica = $a$Submete aos limites do art. 37, XI, os benefícios pagos, a qualquer título, pelo órgão responsável pelo regime geral de previdência social, ainda que à conta do Tesouro Nacional, e os não sujeitos ao limite máximo de valor fixado para os benefícios concedidos por esse regime.$a$ where codigo='cf' and numero=248 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
update legislacao set contexto = $c$Fundo do regime geral de previdência$c$, aplicacao_pratica = $a$Permite que a União constitua fundo integrado por bens, direitos e ativos de qualquer natureza, em adição aos recursos de sua arrecadação, para assegurar o pagamento dos benefícios do regime geral de previdência social, mediante lei que disponha sobre a natureza e a administração do fundo.$a$ where codigo='cf' and numero=250 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)<200;
